#!/usr/bin/env python3
"""Independently rewrite English B-IV-7 role-play and functional communication."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "questions/english"
LESSON = "lesson-english-content-b-iv-7"
SOURCES = [
    ("https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E8%8B%B1%E6%96%87.pdf", "高雄市立鹽埕國民中學公開英文段考", "對話、角色、功能英語與情境回應"),
    ("https://www.bhjh.ntpc.edu.tw/p/406-1000-10627%2Cr111.php?Lang=zh-tw", "新北市立北投國民中學公開定期評量試題頁", "短對話、社交角色與實用溝通"),
    ("https://www.hcjh.ntpc.edu.tw/p/406-1000-7527%2Cr146.php", "新北市立新埔國民中學公開段考試題頁", "英語會話、請求與情境應用"),
]

def refs():
    return [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "english", "locator": l, "observedPattern": "公立學校英語評量以角色、對象、目的與禮貌程度判斷請求、協商、同意、異議、求助及資訊詢問的合宜回應；本題採全新對話情境。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, l in SOURCES]

DATA = [
    ("library request", "You are borrowing a reference book. Which sentence is the most polite way to ask the librarian for help?", ["Could you help me find this book, please?", "Book find me because yesterday.", "You are the book's homework.", "I will ask the shelf to answer."], "A", "Could you help me ...? with please is a polite request to a librarian and clearly states the needed help.", "先辨認說話者與對象，再確認請求句是否禮貌且能完成目的。", ["Identify the speaker as a student borrowing a book.", "Identify the listener as the librarian.", "State the communication goal: finding the book.", "Choose the polite could-you request.", "Reject lines that are ungrammatical or address an object instead of the librarian."]),
    ("market purchase", "At a farmers' market, you want to know the price of a basket of strawberries. What should you say to the seller?", ["Excuse me, how much is this basket?", "The strawberries are asking for a bus.", "I priced the market next winter yesterday.", "Please make the basket a teacher."], "A", "Excuse me gains attention politely and how much asks for the price of the basket.", "將情境目的轉成正確功能問句，並檢查禮貌開場與詢問內容。", ["Identify the role of customer and seller.", "Find the missing information: price.", "Select the question form how much.", "Keep Excuse me as the polite opener.", "Reject sentences that do not ask about cost or contain impossible actions."]),
    ("directions", "You are lost near a sports center. Which line appropriately asks a passerby for directions to the swimming pool?", ["Excuse me, could you tell me how to get to the pool?", "The pool should explain the street to me.", "I got the directions tomorrow at midnight.", "You are a swimming pool, so turn left."], "A", "The first line politely asks a person for a route and names the destination.", "方向問題要同時符合求助對象、目的地與 how to get to 的句型。", ["Recognize that a passerby may provide information.", "Name the destination swimming pool.", "Choose a request for a route.", "Check the polite opener and could-you form.", "Reject person-object confusion and impossible time statements."]),
    ("group negotiation", "Your project partner wants to use all the colored paper. Which response proposes a fair solution?", ["Let's share the paper so both of us can finish our parts.", "Take it all; my work does not matter.", "The paper is angry about the weather.", "I will hide it and refuse to talk."], "A", "Sharing the paper acknowledges both partners and offers a workable plan for completing the project.", "協商題要找既回應衝突又提出可執行方案的句子。", ["Identify the resource conflict.", "Check whether the line recognizes both people's needs.", "Look for a concrete cooperative action.", "Choose sharing the paper.", "Reject surrender, avoidance, or personification that solves nothing."]),
    ("clinic appointment", "At a clinic, you need to change your appointment from Tuesday to Wednesday. Which request fits the situation?", ["Could I move my appointment to Wednesday, please?", "Wednesday moved the clinic because I am a chair.", "I will change the doctor into a calendar.", "The appointment is eating Tuesday."], "A", "The sentence politely asks staff to move an appointment and identifies the requested new day.", "先找要改變的資訊，再用 could I 句型提出清楚且禮貌的請求。", ["Identify the speaker as a patient.", "Identify the requested change: Tuesday to Wednesday.", "Find a sentence that asks permission.", "Choose Could I move my appointment ...?.", "Reject lines that treat days or objects as people."]),
    ("safety response", "A younger student slips near a wet floor. What is the most responsible thing to say first?", ["Please stay still; I will get an adult and keep others away.", "Stand up quickly and run through the water.", "That was funny, so I will leave.", "Ask the wet floor to call the office."], "A", "The first response protects the student, seeks adult help, and reduces further risk.", "安全情境要先選降低風險、照顧受傷者並尋求適當協助的回應。", ["Notice the possible injury and wet-floor hazard.", "Prioritize keeping the student still and safe.", "Add adult help and prevent another slip.", "Choose the responsible instruction.", "Reject rushing, mocking, abandoning, or addressing an inanimate floor."]),
    ("accepting a plan", "Your team suggests meeting after school to rehearse. You agree and can bring the script. What should you say?", ["That works for me. I will bring the script.", "The rehearsal is a blue sandwich.", "No, I agree with nothing and bring no plan.", "After school should rehearse the team."], "A", "That works for me accepts the plan, and the second sentence adds a relevant contribution.", "同意題要找明確接受並補充實際行動的回應。", ["Identify the proposed time after school.", "Check whether the speaker accepts it.", "Find a useful follow-up action involving the script.", "Choose the agreement plus contribution.", "Reject nonsense or responses that cancel the agreement."]),
    ("respectful disagreement", "A teammate wants to delete the introduction, but you think readers need it. Which response disagrees respectfully?", ["I understand your idea, but could we keep a shorter introduction?", "Your idea is terrible; stop talking.", "The introduction is a bicycle, so yes.", "I disagree, and I will not explain anything."], "A", "The response acknowledges the idea, gives a reason for concern, and suggests a compromise without insulting the teammate.", "禮貌異議通常包含理解、but 轉折與可協商的替代方案。", ["Identify the proposed deletion.", "State why the introduction matters to readers.", "Look for a compromise rather than an insult.", "Choose the shorter-introduction suggestion.", "Reject attacks, nonsense, and unexplained refusal."]),
    ("interview answer", "In a volunteer interview, the coordinator asks, 'Why would you like to help at the animal shelter?' Which answer is relevant?", ["I care about animals and want to learn how to help them.", "Because the shelter is a Tuesday color.", "I am a why question at the bus stop.", "No, the animals should interview the weather."], "A", "The answer gives a personal motivation and connects it to the volunteer role, so it directly answers why.", "Why 問句要提供原因或動機，而且內容要貼合申請的角色。", ["Identify the interview question word why.", "Find a reason for wanting the role.", "Check that the reason concerns animals or helping.", "Choose the motivated, relevant answer.", "Reject options that change the topic or misuse why as a noun."]),
    ("integrated travel repair", "Your train is cancelled, and you must tell the station worker, ask about the next train, and remain courteous. Which line does all three?", ["Excuse me, my train was cancelled. Could you tell me when the next one leaves?", "The train is cancelled, so I will shout at everyone.", "You must become the next train because I am late.", "I will leave without asking anyone for information."], "A", "The first line politely gains attention, reports the problem, and asks for the next departure time.", "整合角色題要逐項核對禮貌開場、事件說明與具體資訊請求。", ["Identify the traveller and station worker roles.", "Include the cancelled-train problem.", "Ask for the next departure time.", "Check that Excuse me keeps the tone courteous.", "Choose the only line containing all three communication goals."]),
]

assert len(DATA) == 10
TARGETS = ["A", "B", "C", "D", "B", "C", "D", "A", "B", "C"]
for i, (tag, prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != answer:
        oi, ti = ord(answer) - 65, ord(target) - 65
        correct = options[oi]
        rest = [v for j, v in enumerate(options) if j != oi]
        options = rest[:ti] + [correct] + rest[ti:]
        answer = target
    item = {"id": f"question-english-content-b-iv-7-{i}", "subject": "english", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-english-content-b-iv-7"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校國中英語段考；只研究角色扮演、請求、協商、同意、異議、求助與資訊詢問題型。", "authoringNote": "依官方英語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫角色扮演題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
    (OUT / f"question-english-content-b-iv-7-{i}.json").write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(DATA)} independent questions for {LESSON}")
